// Fetch Football (29 top European, Midweek & African CAF leagues — incl. Simba SC, Yanga, Azam FC) + NBA
// Scans yesterday + today + next 2 days (EAT) so weekend CAF CL / UCL / UEL fixtures appear cleanly
// and late-night matches crossing 00:00 EAT transition cleanly from live -> finished.
const LEAGUES = [
  ['soccer', 'eng.1', 'Premier League'],
  ['soccer', 'esp.1', 'La Liga'],
  ['soccer', 'ita.1', 'Serie A'],
  ['soccer', 'ger.1', 'Bundesliga'],
  ['soccer', 'fra.1', 'Ligue 1'],
  ['soccer', 'uefa.champions', 'UEFA Champions League'],
  ['soccer', 'uefa.europa', 'UEFA Europa League'],
  ['soccer', 'uefa.europa.conf', 'UEFA Conference League'],
  ['soccer', 'caf.champions', 'CAF Champions League'],
  ['soccer', 'caf.confed', 'CAF Confederation Cup'],
  ['soccer', 'caf.nations', 'AFCON'],
  ['soccer', 'caf.nations_qual', 'AFCON Qualifiers'],
  ['soccer', 'rsa.1', 'South African Premiership'],
  ['soccer', 'ken.1', 'Kenyan Premier League'],
  ['soccer', 'uga.1', 'Ugandan Premier League'],
  ['soccer', 'eng.2', 'Championship'],
  ['soccer', 'ned.1', 'Eredivisie'],
  ['soccer', 'por.1', 'Primeira Liga'],
  ['soccer', 'tur.1', 'Turkish Super Lig'],
  ['soccer', 'bra.1', 'Brasileirao'],
  ['soccer', 'arg.1', 'Argentine Primera'],
  ['soccer', 'mex.1', 'Liga MX'],
  ['soccer', 'usa.1', 'MLS'],
  ['soccer', 'sco.1', 'Scottish Premiership'],
  ['soccer', 'bel.1', 'Belgian Pro League'],
  ['soccer', 'ita.2', 'Serie B'],
  ['soccer', 'esp.2', 'La Liga 2'],
  ['soccer', 'ger.2', '2. Bundesliga'],
  ['soccer', 'afc.champions', 'AFC Champions League'],
  ['soccer', 'conmebol.libertadores', 'Copa Libertadores'],
  ['soccer', 'conmebol.sudamericana', 'Copa Sudamericana'],
  ['basketball', 'nba', 'NBA']
];

function americanToDecimal(val) {
  const n = Number(val);
  if (!Number.isFinite(n) || n === 0) return null;
  return n > 0 ? +(1 + n / 100).toFixed(2) : +(1 + 100 / Math.abs(n)).toFixed(2);
}

const now = new Date();
const nowIso = now.toISOString();
const staleCutoffMs = now.getTime() - 4 * 3600 * 1000;
const staleCutoffIso = new Date(staleCutoffMs).toISOString();

const fmtEat = (offsetDays) =>
  new Date(now.getTime() + offsetDays * 86400000)
    .toLocaleDateString('en-CA', { timeZone: 'Africa/Dar_es_Salaam' })
    .replace(/-/g, '');

const dateKeys = [fmtEat(-1), fmtEat(0), fmtEat(1), fmtEat(2), fmtEat(3)];
const byId = new Map();

for (const dateKey of dateKeys) {
  const batch = LEAGUES.map(async ([sportSlug, leagueSlug, leagueName]) => {
    const url = 'https://site.api.espn.com/apis/site/v2/sports/' + sportSlug + '/' + leagueSlug + '/scoreboard?dates=' + dateKey;
    try {
      const data = await this.helpers.httpRequest({ method: 'GET', url, timeout: 9000, json: true });
      return { sportSlug, leagueName, data };
    } catch (e) {
      return { sportSlug, leagueName, data: null };
    }
  });
  const responses = await Promise.all(batch);
  for (const { sportSlug, leagueName, data } of responses) {
    const events = (data && data.events) || [];
    const sport = sportSlug === 'basketball' ? 'basketball' : 'football';
    for (const ev of events) {
      const evId = String(ev.id || '').trim();
      const comp = (ev.competitions && ev.competitions[0]) || null;
      if (!evId || !comp) continue;
      const cs = comp.competitors || [];
      const h = cs.find(c => c.homeAway === 'home');
      const a = cs.find(c => c.homeAway === 'away');
      if (!h || !a) continue;
      const ht = h.team || {};
      const at = a.team || {};
      const homeName = String(ht.displayName || ht.name || '').trim();
      const awayName = String(at.displayName || at.name || '').trim();
      if (!homeName || !awayName) continue;

      const kickoffStr = String(ev.date || nowIso);
      const kickoffMs = Date.parse(kickoffStr);
      const isTooOld = Number.isFinite(kickoffMs) && kickoffMs < staleCutoffMs;

      const st = (ev.status && ev.status.type) || {};
      const state = String(st.state || 'pre').toLowerCase();
      const completed = Boolean(st.completed) || state === 'post' || isTooOld;
      const isLive = !completed && state === 'in';
      const status = completed ? 'finished' : (isLive ? 'live' : 'scheduled');
      const clock = String(st.shortDetail || st.detail || '').trim();
      const hScore = state === 'pre' ? null : (Number.isFinite(parseInt(h.score, 10)) ? parseInt(h.score, 10) : null);
      const aScore = state === 'pre' ? null : (Number.isFinite(parseInt(a.score, 10)) ? parseInt(a.score, 10) : null);

      const oddsArr = Array.isArray(comp.odds) ? comp.odds : [];
      const o0 = oddsArr.find(x => x && typeof x === 'object') || null;
      let oddsHome = null, oddsDraw = null, oddsAway = null, oddsSummary = '';
      if (o0) {
        oddsHome = americanToDecimal(o0.homeTeamOdds && o0.homeTeamOdds.moneyLine);
        oddsAway = americanToDecimal(o0.awayTeamOdds && o0.awayTeamOdds.moneyLine);
        oddsDraw = americanToDecimal(o0.drawOdds && o0.drawOdds.moneyLine);
        const parts = [];
        if (oddsHome && oddsAway) {
          parts.push(oddsDraw
            ? ('1: ' + oddsHome.toFixed(2) + ' · X: ' + oddsDraw.toFixed(2) + ' · 2: ' + oddsAway.toFixed(2))
            : ('1: ' + oddsHome.toFixed(2) + ' · 2: ' + oddsAway.toFixed(2)));
        } else if (o0.details) {
          parts.push(String(o0.details).trim());
        }
        if (o0.overUnder) parts.push('O/U ' + o0.overUnder);
        oddsSummary = parts.join(' | ');
      }

      const id = 'espn-' + sport + '-' + evId;
      byId.set(id, {
        id,
        event_id: evId,
        sport,
        league: leagueName,
        home_team: homeName,
        away_team: awayName,
        home_logo_url: String(ht.logo || '').trim(),
        away_logo_url: String(at.logo || '').trim(),
        kickoff_at: kickoffStr,
        status,
        is_live: isLive,
        home_score: hScore,
        away_score: aScore,
        clock,
        odds_home: oddsHome,
        odds_draw: oddsDraw,
        odds_away: oddsAway,
        odds_summary: oddsSummary,
        source: 'espn-multi',
        is_active: !completed,
        updated_at: nowIso
      });
    }
  }
}

const rows = Array.from(byId.values());
if (!rows.length) return [];
return [{ json: { count: rows.length, stale_cutoff_iso: staleCutoffIso, payload: rows } }];
